import AccountLayout from "@/components/AccountLayout";
import { QuizStudioAiChat } from "@/components/QuizStudioAiChat";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { validateQuestionConfiguration } from "@shared/questionValidation";
import { AlertTriangle, ArrowLeft, BarChart3, Bot, Check, CheckCircle2, ChevronRight, Clock3, Copy, Eye, FileText, Globe2, GripVertical, History, ImagePlus, LayoutGrid, Link2, Loader2, Mail, MoreHorizontal, PencilLine, Plus, QrCode, RotateCcw, SendHorizontal, Settings2, ShieldCheck, Sparkles, Trash2, Wand2, Youtube } from "lucide-react";
import QRCode from "qrcode";
import { useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

type QuestionType = "single" | "multiple" | "true_false" | "true_false_statements" | "fill_blank" | "matching" | "essay";
type Difficulty = "easy" | "medium" | "hard";
type Option = { body: string; isCorrect: boolean };
type Statement = { id: string; text: string; correct: boolean };
type QuestionMedia = { url: string; kind: "audio" | "video"; fileName: string };
type QuizQuestion = { id: string; type: QuestionType; prompt: string; explanation: string; difficulty: Difficulty; points: number; options: Option[]; accepted: string; pairs: Array<{ left: string; right: string }>; statements: Statement[]; outline: string; imageUrl: string; media: QuestionMedia | null };
type SaveStatus = "saved" | "saving" | "error";
type CreatorSettings = { durationMinutes: number; maxAttempts: number; expiresAt: string; shuffleQuestions: boolean; shuffleAnswers: boolean; allowIncorrectContinue: boolean; allowBacktrack: boolean; enableAiTranslation: boolean; enableStudyMaterials: boolean; antiCheatMonitor: boolean; liveMonitoring: boolean; requireRegistration: boolean; requireEmail: boolean; hideFromExplore: boolean; visibility: "public" | "private" };

const questionTypes: Array<{ value: QuestionType; label: string; short: string }> = [
  { value: "single", label: "Trắc nghiệm", short: "Trắc nghiệm" }, { value: "multiple", label: "Nhiều đáp án", short: "Nhiều đáp án" }, { value: "true_false", label: "Đúng / Sai", short: "Đúng / Sai" }, { value: "true_false_statements", label: "Nhận định Có / Không", short: "Nhận định" }, { value: "fill_blank", label: "Câu trả lời ngắn", short: "Trả lời ngắn" }, { value: "matching", label: "Ghép nối", short: "Ghép nối" }, { value: "essay", label: "Bài luận", short: "Bài luận" },
];
const initialSettings: CreatorSettings = { durationMinutes: 15, maxAttempts: 0, expiresAt: "", shuffleQuestions: false, shuffleAnswers: false, allowIncorrectContinue: true, allowBacktrack: true, enableAiTranslation: false, enableStudyMaterials: false, antiCheatMonitor: false, liveMonitoring: false, requireRegistration: true, requireEmail: false, hideFromExplore: false, visibility: "public" };
const createStatement = (index: number): Statement => ({ id: `statement-${Date.now()}-${Math.random().toString(36).slice(2)}-${index}`, text: "", correct: true });
const createQuestion = (type: QuestionType = "single"): QuizQuestion => ({ id: `q-${Date.now()}-${Math.random().toString(36).slice(2)}`, type, prompt: "", explanation: "", difficulty: "medium", points: 1, options: type === "true_false" ? [{ body: "Đúng", isCorrect: true }, { body: "Sai", isCorrect: false }] : type === "multiple" ? [{ body: "Tùy chọn 1", isCorrect: true }, { body: "Tùy chọn 2", isCorrect: true }] : [{ body: "Tùy chọn 1", isCorrect: true }, { body: "Tùy chọn 2", isCorrect: false }], accepted: "", pairs: [{ left: "", right: "" }, { left: "", right: "" }], statements: type === "true_false_statements" ? [createStatement(1), createStatement(2)] : [], outline: "", imageUrl: "", media: null });
const toAnswerConfig = (question: QuizQuestion) => question.type === "fill_blank" ? { acceptedAnswers: question.accepted.split("|").map(value => value.trim()).filter(Boolean) } : question.type === "matching" ? { pairs: question.pairs } : question.type === "true_false_statements" ? { statements: question.statements.map(statement => ({ ...statement, text: statement.text.trim() })) } : question.type === "essay" ? { sampleOutline: question.outline } : {};
const slugify = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 170);

export default function UserQuizCreator() {
  const [editingQuizId] = useState(() => { const id = Number(new URLSearchParams(window.location.search).get("edit")); return Number.isInteger(id) && id > 0 ? id : null; });
  const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [slug, setSlug] = useState(""); const [topicId, setTopicId] = useState(""); const [coverImageUrl, setCoverImageUrl] = useState("");
  const [questions, setQuestions] = useState<QuizQuestion[]>([createQuestion()]); const [selectedId, setSelectedId] = useState(questions[0]!.id); const [settings, setSettings] = useState<CreatorSettings>(initialSettings);
  const initialAiSource = new URLSearchParams(window.location.search).get("ai"); const aiSourceFromUrl = ["topic", "file", "youtube", "web"].includes(initialAiSource ?? "") ? initialAiSource as "topic" | "file" | "youtube" | "web" : null;
  const [activeTab, setActiveTab] = useState<"questions" | "settings" | "analytics">("questions"); const [chatOpen, setChatOpen] = useState(Boolean(aiSourceFromUrl)); const [chatSource, setChatSource] = useState<"topic" | "file" | "youtube" | "web">(aiSourceFromUrl ?? "topic"); const [isAiGenerating, setIsAiGenerating] = useState(false); const [saveStatus, setSaveStatus] = useState<SaveStatus>("saved"); const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null); const [historyOpen, setHistoryOpen] = useState(false); const [publishConfirm, setPublishConfirm] = useState(false); const [highlightedIds, setHighlightedIds] = useState<string[]>([]); const [share, setShare] = useState<{ title: string; url: string; qr: string } | null>(null);
  const draftStorageKey = `dshare-quiz-draft-key-${editingQuizId ?? "new"}`; const [draftKey] = useState(() => { const stored = localStorage.getItem(draftStorageKey); if (stored) return stored; const key = `draft-${editingQuizId ?? "new"}-${crypto.randomUUID?.() ?? Math.random().toString(36).slice(2)}`.slice(0, 96); localStorage.setItem(draftStorageKey, key); return key; }); const [draftReady, setDraftReady] = useState(false);
  const saveTimer = useRef<number | null>(null); const highlightTimer = useRef<number | null>(null); const draftHydrated = useRef(false); const skipNextAutosave = useRef(false); const previousPrivateToggle = useRef(initialSettings.hideFromExplore);
  const utils = trpc.useUtils(); const content = trpc.creator.contentOptions.useQuery(); const editQuery = trpc.creator.getQuizForEdit.useQuery({ quizId: editingQuizId ?? 1 }, { enabled: Boolean(editingQuizId) }); const quizAnalytics = trpc.creator.quizAnalytics.useQuery({ quizId: editingQuizId ?? 1 }, { enabled: Boolean(editingQuizId) && activeTab === "analytics" }); const serverDraft = trpc.creator.getDraft.useQuery({ draftKey }); const draftVersions = trpc.creator.listDraftVersions.useQuery({ draftKey });
  const openShare = async (quizId: number, shareTitle: string) => { const url = `${window.location.origin}/quiz/${quizId}`; try { const qr = await QRCode.toDataURL(url, { width: 300, margin: 1, color: { dark: "#172554", light: "#FFFFFF" } }); setShare({ title: shareTitle, url, qr }); } catch { setShare({ title: shareTitle, url, qr: "" }); } };
  const discardDraft = trpc.creator.deleteDraft.useMutation(); const saveDraft = trpc.creator.saveDraft.useMutation({ onSuccess: result => { setSaveStatus("saved"); setLastSavedAt(result.savedAt); void draftVersions.refetch(); }, onError: () => setSaveStatus("error") }); const restoreDraftVersion = trpc.creator.restoreDraftVersion.useMutation({ onSuccess: result => { skipNextAutosave.current = true; applyDraftPayload(result.payload); setLastSavedAt(result.savedAt); setSaveStatus("saved"); setHistoryOpen(false); void draftVersions.refetch(); toast.success("Đã khôi phục phiên bản nháp."); }, onError: error => toast.error("Không thể khôi phục bản nháp", { description: error.message }) }); const toggleDraftVersionPin = trpc.creator.toggleDraftVersionPin.useMutation({ onSuccess: result => { void draftVersions.refetch(); toast.success(result.isPinned ? "Đã ghim phiên bản nháp." : "Đã bỏ ghim phiên bản nháp."); }, onError: error => toast.error("Không thể cập nhật ghim phiên bản", { description: error.message }) });
  const createQuiz = trpc.creator.createQuiz.useMutation({ onSuccess: result => { setSaveStatus("saved"); toast.success(result.status === "pending_review" ? "Quiz đã được gửi chờ quản trị viên duyệt." : result.visibility === "private" ? "Quiz riêng tư đã được lưu. Chỉ bạn có quyền truy cập." : "Quiz đã được xuất bản."); utils.creator.myQuizzes.invalidate(); discardDraft.mutate({ draftKey }); localStorage.removeItem(draftStorageKey); if (result.status === "published" && result.visibility === "public") void openShare(result.quizId, result.title); }, onError: error => { setSaveStatus("error"); toast.error("Không thể xuất bản Quiz", { description: error.message }); } });
  const updateQuiz = trpc.creator.updateQuiz.useMutation({ onSuccess: result => { setSaveStatus("saved"); toast.success(result.status === "pending_review" ? "Quiz đã được gửi chờ quản trị viên duyệt." : result.visibility === "private" ? "Quiz riêng tư đã được cập nhật." : "Quiz đã được cập nhật và công khai."); utils.creator.myQuizzes.invalidate(); discardDraft.mutate({ draftKey }); localStorage.removeItem(draftStorageKey); if (result.status === "published" && result.visibility === "public") void openShare(result.quizId, result.title); }, onError: error => { setSaveStatus("error"); toast.error("Không thể xuất bản Quiz", { description: error.message }); } });

  const selectedQuestion = questions.find(question => question.id === selectedId) ?? questions[0];
  const autosaveKey = `dshare-quiz-creator-${editingQuizId ?? "new"}`;
  useEffect(() => { if (!editingQuizId || !editQuery.data || draftHydrated.current) return; const loaded = editQuery.data; const restored: QuizQuestion[] = loaded.questions.map((item: any) => ({ id: `loaded-${item.id}`, type: item.type as QuestionType, prompt: item.prompt, explanation: item.explanation ?? "", difficulty: item.difficulty ?? "medium", points: item.points ?? 1, options: item.options ?? [], accepted: item.answerConfig?.acceptedAnswers?.join("|") ?? "", pairs: item.answerConfig?.pairs ?? [{ left: "", right: "" }, { left: "", right: "" }], statements: item.answerConfig?.statements ?? [], outline: item.answerConfig?.sampleOutline ?? "", imageUrl: item.imageUrl ?? "", media: item.answerConfig?.media?.url ? item.answerConfig.media : null }));
    setTitle(loaded.quiz.title); setDescription(loaded.quiz.summary ?? ""); setSlug(loaded.quiz.slug); setTopicId(loaded.quiz.topicId ? String(loaded.quiz.topicId) : ""); setCoverImageUrl(loaded.quiz.coverImageUrl ?? ""); setQuestions(restored.length ? restored : [createQuestion()]); setSelectedId(restored[0]?.id ?? ""); const stored = loaded.quiz.creatorSettings as any; const visibility = (stored?.visibility ?? loaded.quiz.visibility) === "private" ? "private" : "public"; setSettings(current => ({ ...current, durationMinutes: Math.max(1, Math.round(loaded.quiz.durationSeconds / 60)), maxAttempts: Number(stored?.maxAttempts ?? 0), expiresAt: "", shuffleQuestions: Boolean(stored?.shuffleQuestions ?? loaded.quiz.randomizeQuestions), shuffleAnswers: Boolean(stored?.shuffleAnswers ?? loaded.quiz.randomizeOptions), visibility, hideFromExplore: visibility === "private", antiCheatMonitor: Boolean(stored?.antiCheatMonitor), liveMonitoring: Boolean(stored?.liveMonitoring), requireRegistration: stored?.requireRegistration !== false, requireEmail: Boolean(stored?.requireEmail), allowBacktrack: stored?.allowBackNavigation !== false }));
  }, [editingQuizId, editQuery.data]);
  const applyDraftPayload = (payload: any) => { if (!payload?.questions?.length) return; const restored: QuizQuestion[] = payload.questions.map((question: any) => ({ ...createQuestion(question.type as QuestionType), ...question, media: question.media ?? null })); setTitle(payload.title ?? ""); setDescription(payload.description ?? ""); setSlug(payload.slug ?? ""); setTopicId(payload.topicId ?? ""); setCoverImageUrl(payload.coverImageUrl ?? ""); setSettings(current => ({ ...current, ...(payload.settings ?? {}) })); setQuestions(restored); setSelectedId(payload.selectedId ?? restored[0]?.id ?? ""); };
  useEffect(() => { if (draftHydrated.current || serverDraft.isLoading || (editingQuizId && editQuery.isLoading)) return; if (serverDraft.data?.payload) { skipNextAutosave.current = true; applyDraftPayload(serverDraft.data.payload); setLastSavedAt(serverDraft.data.updatedAt ? new Date(serverDraft.data.updatedAt) : null); toast.info("Đã khôi phục bản nháp lưu trên máy chủ."); } draftHydrated.current = true; setDraftReady(true); }, [serverDraft.isLoading, serverDraft.data, editingQuizId, editQuery.isLoading]);
  useEffect(() => { if (previousPrivateToggle.current === settings.hideFromExplore) return; previousPrivateToggle.current = settings.hideFromExplore; setSettings(current => ({ ...current, visibility: settings.hideFromExplore ? "private" : "public" })); }, [settings.hideFromExplore]);
  useEffect(() => () => { if (saveTimer.current) window.clearTimeout(saveTimer.current); if (highlightTimer.current) window.clearTimeout(highlightTimer.current); }, []);
  useEffect(() => { if (!draftReady || isAiGenerating) return; if (skipNextAutosave.current) { skipNextAutosave.current = false; return; } setSaveStatus("saving"); if (saveTimer.current) window.clearTimeout(saveTimer.current); const payload = { title, description, slug, topicId, coverImageUrl, settings, questions, selectedId }; saveTimer.current = window.setTimeout(() => { localStorage.setItem(autosaveKey, JSON.stringify(payload)); saveDraft.mutate({ draftKey, quizId: editingQuizId ?? undefined, title, payload }); }, 5000); return () => { if (saveTimer.current) window.clearTimeout(saveTimer.current); }; }, [title, description, slug, topicId, coverImageUrl, settings, questions, selectedId, draftReady, isAiGenerating, autosaveKey, draftKey, editingQuizId]);

  const updateQuestion = (id: string, patch: Partial<QuizQuestion>) => setQuestions(current => current.map(question => question.id === id ? { ...question, ...patch } : question));
  const addQuestion = (type: QuestionType = "single") => { const next = createQuestion(type); setQuestions(current => [...current, next]); setSelectedId(next.id); setActiveTab("questions"); toast.success(`Đã thêm câu hỏi ${questionTypes.find(item => item.value === type)?.label.toLowerCase() ?? "mới"}.`); };
  const duplicateQuestion = (question: QuizQuestion) => { const duplicate = { ...question, id: `q-${Date.now()}-${Math.random().toString(36).slice(2)}`, prompt: question.prompt ? `${question.prompt} (bản sao)` : "", media: question.media ? { ...question.media } : null }; setQuestions(current => [...current, duplicate]); setSelectedId(duplicate.id); toast.success("Đã nhân bản câu hỏi."); };
  const removeQuestion = (id: string) => { setQuestions(current => { const next = current.filter(question => question.id !== id); if (!next.length) { const replacement = createQuestion(); setSelectedId(replacement.id); return [replacement]; } if (selectedId === id) setSelectedId(next[0]!.id); return next; }); toast.success("Đã xóa câu hỏi."); };
  const changeQuestionType = (id: string, type: QuestionType) => { const defaults = createQuestion(type); updateQuestion(id, { type, options: defaults.options, accepted: defaults.accepted, pairs: defaults.pairs, statements: defaults.statements, outline: defaults.outline }); toast.success(`Đã chuyển sang dạng ${questionTypes.find(item => item.value === type)?.label.toLowerCase() ?? "câu hỏi"}.`); };
  const reorderQuestions = (fromId: string, toId: string) => setQuestions(current => { const fromIndex = current.findIndex(question => question.id === fromId); const toIndex = current.findIndex(question => question.id === toId); if (fromIndex < 0 || toIndex < 0 || fromIndex === toIndex) return current; const next = [...current]; const [moved] = next.splice(fromIndex, 1); next.splice(toIndex, 0, moved!); return next; });
  const openAi = (source: typeof chatSource = "topic") => { setChatSource(source); setActiveTab("questions"); setChatOpen(true); };
  const addAiQuestions = (generated: any[]) => { const created = generated.slice(0, Math.max(0, 50 - questions.length)).map((item: any) => ({ ...createQuestion((item.type as QuestionType) || "single"), prompt: item.prompt ?? "", explanation: item.explanation ?? "", type: (item.type as QuestionType) || "single", difficulty: (item.difficulty as Difficulty) || "medium", options: item.options?.length ? item.options : createQuestion().options, accepted: item.answerConfig?.acceptedAnswers?.join("|") ?? "", pairs: item.answerConfig?.pairs ?? [{ left: "", right: "" }, { left: "", right: "" }], statements: item.answerConfig?.statements ?? [], outline: item.answerConfig?.sampleOutline ?? "" }));
    if (!created.length) return; setQuestions(current => [...current, ...created]); setSelectedId(created[0]!.id); setHighlightedIds(created.map(question => question.id)); if (highlightTimer.current) window.clearTimeout(highlightTimer.current); highlightTimer.current = window.setTimeout(() => setHighlightedIds([]), 2600);
  };
  const questionError = (question: QuizQuestion) => { if (question.prompt.trim().length < 8) return "Mỗi câu hỏi cần có nội dung tối thiểu 8 ký tự."; return validateQuestionConfiguration({ type: question.type, options: question.options, answerConfig: toAnswerConfig(question), imageUrl: question.imageUrl || null }) ?? null; };
  const selectedTopicHasChildren = Boolean(topicId && (content.data?.topics ?? []).some((topic: any) => topic.parentId === Number(topicId)));
  const canPublish = Boolean(topicId && !selectedTopicHasChildren && title.trim().length >= 4 && questions.length && !questions.some(question => questionError(question)));
  const publish = () => { if (!canPublish) return toast.error("Quiz chưa đủ điều kiện xuất bản.", { description: selectedTopicHasChildren ? "Hãy chọn đến Chủ đề cấp cuối cùng." : "Chọn Chủ đề, kiểm tra tên Quiz, nội dung câu hỏi và đáp án đúng." }); const payload = { topicId: Number(topicId), title: title.trim(), summary: description.trim() || undefined, coverImageUrl: coverImageUrl.trim() || undefined, isPublished: true, settings: { durationMinutes: settings.durationMinutes, maxAttempts: settings.maxAttempts, expiresAt: settings.expiresAt ? new Date(settings.expiresAt).toISOString() : undefined, antiCheatMonitor: settings.antiCheatMonitor, hideHintsAndExplanation: false, allowBackNavigation: settings.allowBacktrack, requireRegistration: settings.requireRegistration, liveMonitoring: settings.liveMonitoring, requireEmail: settings.requireEmail, shuffleQuestions: settings.shuffleQuestions, shuffleAnswers: settings.shuffleAnswers, visibility: settings.visibility }, questions: questions.map(question => ({ prompt: question.prompt.trim(), explanation: question.explanation.trim() || undefined, imageUrl: question.imageUrl.trim() || undefined, type: question.type, difficulty: question.difficulty, points: question.points, tags: ["Quiz cá nhân"], options: ["fill_blank", "matching", "true_false_statements", "essay"].includes(question.type) ? [] : question.options.filter(option => option.body.trim()), answerConfig: { ...toAnswerConfig(question), ...(question.media ? { media: question.media } : {}) } })) };
    if (editingQuizId) updateQuiz.mutate({ ...payload, quizId: editingQuizId }); else createQuiz.mutate({ ...payload, slug: slug || slugify(title) || undefined });
  };
  const openSandboxPreview = () => { if (!canPublish) { toast.error("Chưa thể xem trước Quiz.", { description: "Hãy đặt tiêu đề, nội dung câu hỏi và ít nhất một đáp án đúng cho mỗi câu." }); return; } const preview = { title: title.trim(), summary: description.trim(), durationSeconds: settings.durationMinutes * 60, questions: questions.map((question, index) => ({ id: -(index + 1), prompt: question.prompt.trim(), type: question.type, difficulty: question.difficulty, tags: ["Sandbox"], explanation: question.explanation || null, imageUrl: question.imageUrl || null, media: question.media, statements: question.type === "true_false_statements" ? question.statements : [], options: question.options.filter(option => option.body.trim()).map((option, optionIndex) => ({ id: optionIndex + 1, body: option.body })), correctOptionIds: question.options.reduce<number[]>((ids, option, optionIndex) => option.isCorrect ? [...ids, optionIndex + 1] : ids, []) })) }; sessionStorage.setItem("dshare-quiz-preview", JSON.stringify(preview)); window.open("/quiz/0?sandbox=1", "_blank", "noopener,noreferrer"); toast.success("Đã mở Quiz Runner ở chế độ Sandbox."); };

  if (editingQuizId && editQuery.isLoading) return <AccountLayout><main className="grid min-h-screen place-items-center bg-[#f5f7fc]"><Loader2 className="animate-spin text-[#065be5]" /></main></AccountLayout>;
  return <AccountLayout hideSidebar staticHeader><main className="quiz-studio-synchronous flex min-h-[calc(100vh-72px)] flex-col p-3 sm:p-5 bg-[#f5f7fc] text-[#172554]">
    {!chatOpen ? <CreatorHeader title={title} questionCount={questions.length} activeTab={activeTab} saveStatus={saveStatus} lastSavedAt={lastSavedAt} canPublish={canPublish} canAnalyze={Boolean(editingQuizId)} isPublishing={createQuiz.isPending || updateQuiz.isPending} onBack={() => window.history.back()} onTitle={setTitle} onTab={setActiveTab} onHistory={() => setHistoryOpen(true)} onPreview={openSandboxPreview} onPublish={() => setPublishConfirm(true)} /> : null}
    {chatOpen ? <section data-testid="spec-quiz-workspace" className="mx-auto mt-4 flex w-full max-w-[1680px] flex-col gap-4 xl:flex-row xl:items-start xl:justify-center"><CompactQuestionRail title={title} onTitle={setTitle} questions={questions} selectedId={selectedId} onSelect={setSelectedId} onUpdate={updateQuestion} onDuplicate={duplicateQuestion} onRemove={removeQuestion} onTypeChange={changeQuestionType} onReorder={reorderQuestions} /><QuizStudioAiChat variant="primary" source={chatSource} title={title} summary={description} questionCount={questions.length} onClose={() => { setChatOpen(false); setIsAiGenerating(false); }} onGenerated={addAiQuestions} onBusyChange={setIsAiGenerating} /></section> : activeTab === "analytics" ? <QuizAnalyticsWorkspace analytics={quizAnalytics} /> : activeTab === "settings" ? <SettingsWorkspace title={title} description={description} slug={slug} topicId={topicId} coverImageUrl={coverImageUrl} settings={settings} content={content.data} onTitle={setTitle} onDescription={setDescription} onSlug={(value: string) => setSlug(slugify(value))} onTopic={setTopicId} onCover={setCoverImageUrl} onSettings={setSettings} /> : <section data-testid="spec-quiz-workspace" className="mx-auto mt-4 max-w-[1680px] xl:grid xl:grid-cols-[240px_minmax(0,1fr)_72px] xl:items-start xl:gap-4"><QuestionNavigator questions={questions} selectedId={selectedId} onSelect={setSelectedId} /><EditorCanvas questions={questions} selectedId={selectedId} highlightedIds={highlightedIds} locked={isAiGenerating} onUpdate={updateQuestion} onSelect={setSelectedId} onDuplicate={duplicateQuestion} onRemove={removeQuestion} onAdd={addQuestion} onOpenAi={openAi} onReorder={reorderQuestions} /><FloatingToolbar onOpenAi={() => openAi("topic")} onAdd={() => addQuestion()} onSelectAll={() => toast.info("Đã chọn toàn bộ câu hỏi trong danh sách.")} /></section>}
    <AlertDialog open={publishConfirm} onOpenChange={setPublishConfirm}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Xuất bản Quiz công khai?</AlertDialogTitle><AlertDialogDescription>Quiz sẽ được công khai để người học có thể truy cập và làm bài. Bạn có thể chỉnh sửa lại sau khi xuất bản.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Hủy</AlertDialogCancel><AlertDialogAction onClick={publish}>Xác nhận xuất bản</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <ShareQuizDialog share={share} onClose={() => setShare(null)} />
    <DraftHistoryDialog open={historyOpen} onOpenChange={setHistoryOpen} versions={draftVersions.data ?? []} isLoading={draftVersions.isLoading} currentSnapshot={{ title, description, questions }} restoringId={restoreDraftVersion.isPending ? restoreDraftVersion.variables?.versionId : null} pinningId={toggleDraftVersionPin.isPending ? toggleDraftVersionPin.variables?.versionId : null} onRestore={(versionId: number) => restoreDraftVersion.mutate({ draftKey, versionId })} onTogglePin={(versionId: number, isPinned: boolean) => toggleDraftVersionPin.mutate({ draftKey, versionId, isPinned })} />
  </main></AccountLayout>;
}

export function ShareQuizDialog({ share, onClose }: { share: { title: string; url: string; qr: string } | null; onClose: () => void }) { const copyLink = async () => { try { await navigator.clipboard.writeText(share?.url ?? ""); toast.success("Đã sao chép liên kết chia sẻ."); } catch { toast.error("Không thể sao chép liên kết."); } }; const openShare = (channel: "facebook" | "zalo" | "email") => { if (!share) return; const encodedUrl = encodeURIComponent(share.url); if (channel === "email") { window.location.href = `mailto:?subject=${encodeURIComponent(`Mời bạn làm Quiz: ${share.title}`)}&body=${encodeURIComponent(`Mời bạn tham gia Quiz \"${share.title}\":\n${share.url}`)}`; return; } const url = channel === "facebook" ? `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}` : `https://zalo.me/share?url=${encodedUrl}`; window.open(url, "_blank", "noopener,noreferrer"); }; return <Dialog open={Boolean(share)} onOpenChange={open => !open && onClose()}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle className="flex items-center gap-2"><CheckCircle2 className="text-[#007453]" />Quiz đã được xuất bản</DialogTitle><DialogDescription>Người học có thể quét mã QR hoặc mở liên kết để làm <strong>{share?.title}</strong>.</DialogDescription></DialogHeader><div className="grid gap-4 rounded-2xl bg-[#f5f7fc] p-4 sm:grid-cols-[148px_1fr]"><div className="grid min-h-36 place-items-center rounded-xl bg-white p-2 shadow-sm">{share?.qr ? <img src={share.qr} alt="Mã QR liên kết Quiz" className="h-32 w-32" /> : <QrCode className="text-[#71838d]" />}</div><div className="min-w-0"><p className="text-xs font-bold text-[#25324d]">Liên kết chia sẻ</p><p className="mt-2 break-all rounded-xl border border-[#172554]/10 bg-white p-3 text-xs text-[#617786]">{share?.url}</p><Button type="button" variant="outline" onClick={copyLink} className="mt-3 w-full rounded-xl text-xs"><Copy size={14} />Sao chép liên kết</Button><div className="mt-3 grid grid-cols-3 gap-2"><Button type="button" variant="outline" onClick={() => openShare("facebook")} className="rounded-xl border-[#1877f2]/25 bg-[#f4f8ff] px-2 text-[11px] text-[#1877f2] hover:bg-[#eaf2ff]" aria-label="Chia sẻ lên Facebook"><span className="font-black">f</span><span className="hidden sm:inline">Facebook</span></Button><Button type="button" variant="outline" onClick={() => openShare("zalo")} className="rounded-xl border-[#0068ff]/25 bg-[#f2f7ff] px-2 text-[11px] text-[#0068ff] hover:bg-[#e7f0ff]" aria-label="Chia sẻ qua Zalo"><span className="font-black">Z</span><span className="hidden sm:inline">Zalo</span></Button><Button type="button" variant="outline" onClick={() => openShare("email")} className="rounded-xl border-[#7057e8]/25 bg-[#f7f4ff] px-2 text-[11px] text-[#7057e8] hover:bg-[#f0ebff]" aria-label="Chia sẻ qua Email"><Mail size={13} /><span className="hidden sm:inline">Email</span></Button></div></div></div><DialogFooter><Button type="button" onClick={onClose} className="rounded-xl bg-[#065be5]">Hoàn tất</Button></DialogFooter></DialogContent></Dialog>; }

function CreatorHeader({ title, questionCount, activeTab, saveStatus, lastSavedAt, canPublish, canAnalyze, isPublishing, onBack, onTitle, onTab, onHistory, onPreview, onPublish }: any) {
  const savedAtText = lastSavedAt ? new Date(lastSavedAt).toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" }) : "";
  const state = saveStatus === "saving" ? { label: "Đang lưu…", icon: Loader2, tone: "border-[#7057e8]/20 bg-[#f7f4ff] text-[#7057e8]" } : saveStatus === "error" ? { label: "Lỗi kết nối", icon: AlertTriangle, tone: "border-[#de1264]/20 bg-[#fff1f6] text-[#de1264]" } : { label: savedAtText ? `Đã lưu lúc ${savedAtText}` : "Đã lưu", icon: CheckCircle2, tone: "border-[#007453]/20 bg-[#effaf5] text-[#007453]" };
  const Icon = state.icon;
  return <header data-testid="spec-creator-header" className="mx-auto grid max-w-[1680px] grid-cols-1 items-center gap-3 rounded-2xl border border-[#172554]/10 bg-white p-3 shadow-[0_10px_28px_rgba(20,44,91,.06)] lg:grid-cols-[1fr_auto_1fr]"><div className="flex min-w-0 items-center gap-3"><Button type="button" variant="ghost" size="icon" onClick={onBack} className="rounded-xl bg-[#f4f7ff] text-[#065be5]" aria-label="Quay lại"><ArrowLeft size={18} /></Button><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-[#065be5] to-[#7057e8] text-xs font-black text-white">D</span><div className="min-w-0"><Input aria-label="Tiêu đề Quiz ở thanh menu Studio" value={title} onChange={event => onTitle(event.target.value)} className="h-7 border-0 bg-transparent px-0 text-sm font-bold shadow-none focus-visible:ring-0" placeholder="Đặt tên cho Quiz" /><span className="text-[10px] text-[#71838d]">{questionCount} câu hỏi · Bản nháp</span></div></div><div className="flex justify-center rounded-xl bg-[#f4f5f9] p-1"><button type="button" onClick={() => onTab("questions")} className={`rounded-lg px-4 py-2 text-xs font-bold ${activeTab === "questions" ? "bg-white text-[#172554] shadow-sm" : "text-[#71838d]"}`}>Câu hỏi</button><button type="button" onClick={() => onTab("settings")} className={`rounded-lg px-4 py-2 text-xs font-bold ${activeTab === "settings" ? "bg-white text-[#172554] shadow-sm" : "text-[#71838d]"}`}>Cài đặt</button>{canAnalyze ? <button type="button" onClick={() => onTab("analytics")} className={`rounded-lg px-4 py-2 text-xs font-bold ${activeTab === "analytics" ? "bg-white text-[#172554] shadow-sm" : "text-[#71838d]"}`}>Phân tích</button> : null}</div><div className="flex items-center justify-end gap-2"><span data-testid="autosave-indicator" role="status" aria-live="polite" className={`flex items-center gap-1.5 rounded-full border px-2.5 py-1.5 text-[11px] font-bold ${state.tone}`}><Icon size={14} className={saveStatus === "saving" ? "animate-spin" : ""} />{state.label}</span><Button type="button" variant="outline" size="icon" onClick={onHistory} className="h-9 w-9 rounded-xl" aria-label="Lịch sử bản nháp"><History size={16} /></Button><Button type="button" onClick={onPublish} disabled={!canPublish || isPublishing} className="rounded-xl bg-[#065be5] px-4 text-xs hover:bg-[#054fc5]"><SendHorizontal size={15} />{isPublishing ? "Đang xuất bản…" : "Xuất bản"}</Button><Button type="button" variant="outline" size="icon" onClick={onPreview} className="h-9 w-9 rounded-xl border-[#065be5]/20 bg-white text-[#065be5]" aria-label="Xem trước Sandbox" title="Xem trước Sandbox"><Eye size={16} /></Button></div></header>;
}

function QuizAnalyticsWorkspace({ analytics }: { analytics: any }) {
  if (analytics.isLoading) return <section className="mx-auto mt-4 grid min-h-72 max-w-[1120px] place-items-center rounded-2xl border border-[#172554]/10 bg-white"><p role="status" className="flex items-center gap-2 text-sm text-[#617786]"><Loader2 className="animate-spin text-[#065be5]" size={17} />Đang tổng hợp dữ liệu Quiz…</p></section>;
  if (analytics.isError) return <section className="mx-auto mt-4 max-w-[1120px] rounded-2xl border border-[#de1264]/20 bg-white p-8 text-center"><AlertTriangle className="mx-auto text-[#de1264]" size={26} /><h2 className="mt-3 text-lg font-bold text-[#25324d]">Chưa tải được phân tích</h2><p className="mt-2 text-sm text-[#71838d]">{analytics.error?.message || "Dữ liệu tạm thời chưa sẵn sàng."}</p><Button type="button" variant="outline" onClick={() => analytics.refetch()} className="mt-5 rounded-xl text-[#065be5]">Thử lại</Button></section>;
  const data = analytics.data;
  if (!data) return null;
  const latest = data.summary.latestCompletedAt ? new Date(data.summary.latestCompletedAt).toLocaleString("vi-VN", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "Chưa có";
  return <section data-testid="quiz-analytics-workspace" className="mx-auto mt-4 max-w-[1120px] space-y-5"><div className="rounded-2xl bg-gradient-to-r from-[#065be5] to-[#3762d2] p-5 text-white shadow-[0_14px_30px_rgba(6,91,229,.16)]"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-white/70"><BarChart3 size={14} />Phân tích Quiz</p><h2 className="mt-2 text-xl font-bold">Hiệu quả làm bài của người học</h2><p className="mt-1 text-sm text-white/80">Dữ liệu chỉ dựa trên các lượt làm đã nộp của Quiz này.</p></div><p className="rounded-full bg-white/15 px-3 py-1.5 text-xs font-semibold">Cập nhật gần nhất: {latest}</p></div></div><div className="grid gap-3 sm:grid-cols-3"><AnalyticsStat label="Lượt làm hoàn tất" value={data.summary.completedAttempts} detail="Phiên đã nộp bài" tone="blue" /><AnalyticsStat label="Điểm trung bình" value={`${data.summary.averageScore}%`} detail="Trên thang điểm 100" tone="purple" /><AnalyticsStat label="Tỷ lệ đạt" value={`${data.summary.passRate}%`} detail="Đạt ngưỡng của Quiz" tone="green" /></div>{data.summary.completedAttempts === 0 ? <div className="rounded-2xl border border-dashed border-[#065be5]/30 bg-white p-9 text-center"><BarChart3 className="mx-auto text-[#065be5]" size={26} /><h3 className="mt-3 text-base font-bold text-[#25324d]">Chưa đủ dữ liệu để phân tích</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#71838d]">Khi có lượt làm đã nộp, hệ thống sẽ hiển thị điểm trung bình và tỷ lệ trả lời đúng/sai của từng câu hỏi tại đây.</p></div> : <section className="overflow-hidden rounded-2xl border border-[#172554]/10 bg-white"><div className="border-b border-[#172554]/8 px-5 py-4"><h3 className="text-sm font-bold text-[#25324d]">Tỷ lệ đúng theo câu hỏi</h3><p className="mt-1 text-xs text-[#71838d]">Xác định câu cần xem lại dựa trên câu trả lời đã lưu trong các lượt làm hoàn tất.</p></div><div className="divide-y divide-[#172554]/8">{data.questions.map((item: any, index: number) => { const rate = item.correctRate; const tone = rate === null ? "bg-[#eef1f7]" : rate < 40 ? "bg-[#de1264]" : rate < 70 ? "bg-[#7057e8]" : "bg-[#007453]"; return <article key={item.questionId} className="p-5"><div className="flex items-start justify-between gap-4"><div className="min-w-0"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71838d]">Câu {index + 1} · {item.points} điểm</p><p className="mt-1 line-clamp-2 text-sm font-semibold leading-6 text-[#25324d]">{item.prompt}</p></div><div className="shrink-0 text-right"><p className="text-lg font-black text-[#25324d]">{rate === null ? "—" : `${rate}%`}</p><p className="text-[10px] text-[#71838d]">{item.answerCount} lượt trả lời</p></div></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#eef1f7]"><div className={`h-full rounded-full ${tone}`} style={{ width: `${rate ?? 0}%` }} /></div><p className="mt-2 text-[11px] text-[#71838d]">{rate === null ? "Chưa có lượt trả lời cho câu này." : `${item.correctCount}/${item.answerCount} lượt trả lời đúng.`}</p></article>; })}</div></section>}</section>;
}
function AnalyticsStat({ label, value, detail, tone }: { label: string; value: string | number; detail: string; tone: "blue" | "purple" | "green" }) { const tones = { blue: "bg-[#eef4ff] text-[#065be5]", purple: "bg-[#f2efff] text-[#7057e8]", green: "bg-[#effaf5] text-[#007453]" }; return <article className="rounded-2xl border border-[#172554]/10 bg-white p-4"><span className={`inline-flex rounded-lg px-2 py-1 text-[10px] font-bold ${tones[tone]}`}>{label}</span><p className="mt-3 text-2xl font-black text-[#25324d]">{value}</p><p className="mt-1 text-xs text-[#71838d]">{detail}</p></article>; }

function DraftHistoryDialog({ open, onOpenChange, versions, isLoading, currentSnapshot, restoringId, pinningId, onRestore, onTogglePin }: any) { const [selectedVersion, setSelectedVersion] = useState<any | null>(null); const formatSavedAt = (value: Date | string) => new Date(value).toLocaleString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }); const describe = (payload: any) => ({ title: payload?.title?.trim() || "Quiz chưa đặt tên", description: payload?.description?.trim() || "", questionCount: Array.isArray(payload?.questions) ? payload.questions.length : 0 }); const current = describe(currentSnapshot); const selected = selectedVersion ? describe(selectedVersion.payload) : null; return <Dialog open={open} onOpenChange={value => { if (!value) setSelectedVersion(null); onOpenChange(value); }}><DialogContent className="max-h-[80vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle className="flex items-center gap-2"><History className="text-[#065be5]" size={19} />Lịch sử bản nháp</DialogTitle><DialogDescription>Ghim những phiên bản quan trọng. Hãy đối chiếu thay đổi trước khi khôi phục để tránh ghi đè nội dung đang soạn.</DialogDescription></DialogHeader>{selectedVersion && selected ? <section className="rounded-2xl border border-[#065be5]/20 bg-[#f7faff] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold text-[#065be5]">Đối chiếu trước khi khôi phục</p><p className="mt-1 text-[11px] text-[#71838d]">Phiên bản: {formatSavedAt(selectedVersion.savedAt)}</p></div><Button type="button" variant="ghost" onClick={() => setSelectedVersion(null)} className="h-8 rounded-lg text-xs">Đóng đối chiếu</Button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><DraftCompareCell label="Bản đang soạn" data={current} /><DraftCompareCell label="Phiên bản đã chọn" data={selected} highlight /></div><div className="mt-4 flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setSelectedVersion(null)} className="rounded-lg text-xs">Hủy</Button><Button type="button" onClick={() => onRestore(selectedVersion.id)} disabled={restoringId === selectedVersion.id} className="rounded-lg bg-[#065be5] text-xs"><RotateCcw size={14} className={restoringId === selectedVersion.id ? "animate-spin" : ""} />{restoringId === selectedVersion.id ? "Đang khôi phục" : "Xác nhận khôi phục"}</Button></div></section> : null}{isLoading ? <div className="grid min-h-32 place-items-center"><Loader2 className="animate-spin text-[#065be5]" /></div> : versions.length ? <div className="space-y-2">{versions.map((version: any, index: number) => { const questionCount = Array.isArray(version.payload?.questions) ? version.payload.questions.length : 0; const isPinning = pinningId === version.id; return <div key={version.id} className={`flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3 ${version.isPinned ? "border-[#7057e8]/25 bg-[#faf8ff]" : "border-[#172554]/10 bg-[#fafbff]"}`}><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-xs font-bold text-[#25324d]">{version.title || "Quiz chưa đặt tên"}</p>{version.isPinned ? <span className="rounded-full bg-[#f2efff] px-1.5 py-0.5 text-[9px] font-bold text-[#7057e8]">Đã ghim</span> : null}{index === 0 && !version.isPinned ? <span className="rounded-full bg-[#effaf5] px-1.5 py-0.5 text-[9px] font-bold text-[#007453]">Gần nhất</span> : null}</div><p className="mt-1 text-[11px] text-[#71838d]">{formatSavedAt(version.savedAt)} · {questionCount} câu hỏi</p></div><div className="flex items-center gap-2"><Button type="button" variant="outline" size="icon" onClick={() => onTogglePin(version.id, !version.isPinned)} disabled={isPinning} className={`h-8 w-8 rounded-lg ${version.isPinned ? "border-[#7057e8]/30 bg-[#f2efff] text-[#7057e8]" : "text-[#71838d]"}`} aria-label={`${version.isPinned ? "Bỏ ghim" : "Ghim"} phiên bản nháp ${version.id}`}>{isPinning ? <Loader2 size={14} className="animate-spin" /> : <span className="text-sm">{version.isPinned ? "●" : "○"}</span>}</Button><Button type="button" variant="outline" onClick={() => setSelectedVersion(version)} className="rounded-lg px-2.5 text-xs text-[#065be5]">So sánh</Button></div></div>; })}</div> : <div className="rounded-xl bg-[#f5f7fc] p-5 text-center"><History className="mx-auto text-[#71838d]" /><p className="mt-2 text-sm font-bold text-[#25324d]">Chưa có phiên bản nháp</p><p className="mt-1 text-xs text-[#71838d]">Phiên bản sẽ xuất hiện sau khi Studio tự động lưu thay đổi của bạn.</p></div>}<DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl">Đóng</Button></DialogFooter></DialogContent></Dialog>; }
function DraftCompareCell({ label, data, highlight = false }: { label: string; data: { title: string; description: string; questionCount: number }; highlight?: boolean }) { return <div className={`rounded-xl p-3 ${highlight ? "bg-white shadow-sm" : "bg-white/70"}`}><p className="text-[10px] font-bold uppercase tracking-[.1em] text-[#71838d]">{label}</p><p className="mt-2 truncate text-sm font-bold text-[#25324d]">{data.title}</p><p className="mt-1 line-clamp-2 min-h-8 text-[11px] leading-4 text-[#71838d]">{data.description || "Chưa có mô tả"}</p><p className="mt-3 text-xs font-semibold text-[#065be5]">{data.questionCount} câu hỏi</p></div>; }

function QuestionNavigator({ questions, selectedId, onSelect }: { questions: QuizQuestion[]; selectedId: string; onSelect: (id: string) => void }) { return <aside data-testid="question-navigator" className="rounded-2xl border border-[#172554]/10 bg-white p-4 shadow-[0_10px_28px_rgba(20,44,91,.04)]"><div className="flex items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#065be5]">Danh sách câu hỏi</p><p className="mt-1 text-xs text-[#71838d]">{questions.length} / 50 câu hỏi</p></div><LayoutGrid size={17} className="text-[#71838d]" /></div><div data-testid="question-navigator-scroll" className="mt-4 grid gap-2">{questions.map((question, index) => <button key={question.id} type="button" onClick={() => onSelect(question.id)} className={`min-w-0 rounded-xl border p-3 text-left transition ${selectedId === question.id ? "border-[#065be5]/35 bg-[#eef4ff] shadow-sm" : "border-[#172554]/8 bg-white hover:border-[#065be5]/25"}`}><span className="flex items-center justify-between text-[10px] font-bold"><span>#{index + 1}</span><span className="rounded-full bg-white px-1.5 py-0.5 text-[#71838d]">{questionTypes.find(item => item.value === question.type)?.short}</span></span><span className="mt-2 block truncate text-xs font-semibold text-[#25324d]">{question.prompt || "Câu hỏi chưa có nội dung"}</span></button>)}</div></aside>; }

function CompactQuestionRail({ title, onTitle, questions, selectedId, onSelect, onUpdate, onDuplicate, onRemove, onTypeChange, onReorder }: { title: string; onTitle: (value: string) => void; questions: QuizQuestion[]; selectedId: string; onSelect: (id: string) => void; onUpdate: (id: string, patch: Partial<QuizQuestion>) => void; onDuplicate: (question: QuizQuestion) => void; onRemove: (id: string) => void; onTypeChange: (id: string, type: QuestionType) => void; onReorder: (fromId: string, toId: string) => void }) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const updateOption = (question: QuizQuestion, optionIndex: number, body: string) => onUpdate(question.id, { options: question.options.map((option, index) => index === optionIndex ? { ...option, body } : option) });
  const updateCorrect = (question: QuizQuestion, optionIndex: number) => onUpdate(question.id, { options: question.options.map((option, index) => ({ ...option, isCorrect: question.type === "multiple" ? index === optionIndex ? !option.isCorrect : option.isCorrect : index === optionIndex })) });
  const completedCount = questions.filter(question => {
    if (!question.prompt.trim()) return false;
    if (["single", "multiple", "true_false"].includes(question.type)) return question.options.filter(option => option.body.trim()).length >= 2 && question.options.some(option => option.isCorrect);
    if (question.type === "matching") return question.pairs.some(pair => pair.left.trim() && pair.right.trim());
    if (question.type === "fill_blank") return Boolean(question.accepted.trim());
    return true;
  }).length;
  const completionPercent = questions.length ? Math.round((completedCount / questions.length) * 100) : 0;
  return <QuestionRailLayout title={title} onTitle={onTitle} questions={questions} selectedId={selectedId} draggedId={draggedId} onSelect={onSelect} onUpdate={onUpdate} onDuplicate={onDuplicate} onRemove={onRemove} onTypeChange={onTypeChange} onReorder={onReorder} onDragStart={setDraggedId} onDragEnd={() => setDraggedId(null)} onUpdateOption={updateOption} onUpdateCorrect={updateCorrect} />;
  return <aside className="min-w-0 xl:sticky xl:top-0 xl:flex xl:h-[calc(100vh-88px)] xl:items-center"><section className="flex h-auto min-h-52 w-full flex-col overflow-hidden rounded-[24px] border border-[#172554]/10 bg-white shadow-[0_12px_30px_rgba(20,44,91,.06)] xl:h-full"><header className="border-b border-[#172554]/8 px-5 py-4"><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><label htmlFor="quiz-title-question-tab" className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71838d]">Tiêu đề Quiz</label><div className="mt-1 flex items-center gap-2"><Input id="quiz-title-question-tab" aria-label="Tiêu đề Quiz trong tab Câu hỏi" value={title} onChange={event => onTitle(event.target.value)} className="h-9 min-w-0 border-[#172554]/10 bg-[#f8f9fc] px-2.5 text-sm font-bold text-[#172554]" placeholder="Đặt tên cho Quiz" /><PencilLine size={15} className="shrink-0 text-[#71838d]" /></div></div><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#f4f7ff] text-[#065be5]"><LayoutGrid size={16} /></span></div><div className="mt-3 flex items-center justify-between gap-3 text-[11px] font-semibold"><span className="text-[#35415a]">Tổng <strong className="text-[#065be5]">{questions.length}</strong> câu hỏi</span><span aria-live="polite" className={completedCount === questions.length && questions.length ? "text-[#007453]" : "text-[#71838d]"}>{completedCount}/{questions.length} hoàn thành</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#eef1f7]"><div className="h-full rounded-full bg-gradient-to-r from-[#065be5] to-[#7057e8] transition-[width] duration-200" style={{ width: `${completionPercent}%` }} /></div></header><div className="min-h-0 flex-1 overflow-y-auto p-4"><QuestionRailCards questions={questions} selectedId={selectedId} draggedId={draggedId} onSelect={onSelect} onUpdate={onUpdate} onDuplicate={onDuplicate} onRemove={onRemove} onTypeChange={onTypeChange} onReorder={onReorder} onDragStart={setDraggedId} onDragEnd={() => setDraggedId(null)} onUpdateOption={updateOption} onUpdateCorrect={updateCorrect} /></div><footer className="border-t border-[#172554]/8 bg-[#fafffd] px-5 py-3 text-[11px] leading-4 text-[#007453]">Câu mới từ AI sẽ xuất hiện tại đây.</footer></section></aside>;
  return <aside className="min-w-0 xl:sticky xl:top-0 xl:flex xl:h-[calc(100vh-88px)] xl:items-center"><section className="flex h-auto min-h-52 flex-col overflow-hidden rounded-[24px] border border-[#172554]/10 bg-white shadow-[0_12px_30px_rgba(20,44,91,.06)] xl:h-[80%]"><header className="flex items-center justify-between border-b border-[#172554]/8 px-5 py-4"><div><p className="text-sm font-bold text-[#172554]">Câu hỏi</p><p className="mt-1 text-[11px] text-[#71838d]">{questions.length} câu trong Quiz</p></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#f4f7ff] text-[#065be5]"><LayoutGrid size={16} /></span></header><div className="min-h-0 flex-1 overflow-y-auto p-4"><div className="mx-auto max-w-[650px] space-y-4">{questions.map((question, index) => <article key={question.id} draggable onDragStart={() => setDraggedId(question.id)} onDragEnd={() => setDraggedId(null)} onDragOver={event => event.preventDefault()} onDrop={() => { if (draggedId) onReorder(draggedId, question.id); setDraggedId(null); }} onClick={() => onSelect(question.id)} className={`rounded-2xl border bg-white p-4 shadow-[0_2px_8px_rgba(20,44,91,.05)] transition ${selectedId === question.id ? "border-[#7057e8]/40 ring-2 ring-[#7057e8]/8" : "border-[#172554]/8 hover:border-[#065be5]/25"} ${draggedId === question.id ? "opacity-50" : ""}`}><div className="mb-4 flex items-center gap-2"><span title="Kéo để sắp xếp" className="cursor-grab text-[#aab4c4] active:cursor-grabbing"><GripVertical size={17} /></span><span className="text-base font-black text-[#25324d]">#{index + 1}</span><select aria-label={`Loại câu hỏi trong tab ${index + 1}`} value={question.type} onClick={event => event.stopPropagation()} onChange={event => onTypeChange(question.id, event.target.value as QuestionType)} className="h-9 min-w-0 flex-1 rounded-lg border border-[#172554]/10 bg-[#f8f9fc] px-2.5 text-xs font-bold text-[#35415a]"><option value="single">● Trắc nghiệm</option><option value="multiple">● Nhiều đáp án</option><option value="true_false">⇄ Đúng / Sai</option><option value="fill_blank">⌁ Trả lời ngắn</option><option value="matching">▦ Ghép nối</option><option value="essay">✎ Bài luận</option></select><div className="flex gap-1"><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onDuplicate(question); }} className="h-8 w-8 rounded-lg" aria-label={`Nhân bản câu hỏi ${index + 1} trong tab`}><Copy size={14} /></Button><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onRemove(question.id); }} className="h-8 w-8 rounded-lg text-[#de1264]" aria-label={`Xóa câu hỏi ${index + 1} trong tab`}><Trash2 size={14} /></Button></div></div><Textarea aria-label={`Nội dung câu hỏi ${index + 1} trong tab`} value={question.prompt} onClick={event => event.stopPropagation()} onChange={event => onUpdate(question.id, { prompt: event.target.value })} className="min-h-16 resize-none border-0 bg-transparent px-0 py-0 text-sm font-bold leading-6 shadow-none focus-visible:ring-0" placeholder="Nhập nội dung câu hỏi" />{["single", "multiple", "true_false"].includes(question.type) ? <div className="mt-4 space-y-2">{question.options.slice(0, 3).map((option, optionIndex) => <div key={optionIndex} className="flex min-w-0 items-center gap-2.5"><button type="button" aria-label={`Đánh dấu đáp án ${optionIndex + 1} câu ${index + 1}`} onClick={event => { event.stopPropagation(); updateCorrect(question, optionIndex); }} className={`grid h-5 w-5 shrink-0 place-items-center rounded-full text-[10px] ${option.isCorrect ? "bg-[#14c973] text-white" : "border border-[#cbd5e1] bg-white"}`}>{option.isCorrect ? <Check size={12} /> : ""}</button><Input aria-label={`Đáp án ${optionIndex + 1} câu ${index + 1} trong tab`} value={option.body} onClick={event => event.stopPropagation()} onChange={event => updateOption(question, optionIndex, event.target.value)} className="h-8 border-0 bg-[#f8f9fc] px-2 text-sm text-[#617786] shadow-none focus-visible:ring-1" placeholder={`Tùy chọn ${optionIndex + 1}`} /></div>)}</div> : <p className="mt-4 text-xs text-[#71838d]">{questionTypes.find(item => item.value === question.type)?.label}</p>}</article>)}</div></div><footer className="border-t border-[#172554]/8 bg-[#fafffd] px-5 py-3 text-[11px] leading-4 text-[#007453]">Câu mới từ AI sẽ xuất hiện tại đây.</footer></section></aside>;
}

function QuestionRailLayout({ title, onTitle, questions, selectedId, draggedId, onSelect, onUpdate, onDuplicate, onRemove, onTypeChange, onReorder, onDragStart, onDragEnd, onUpdateOption, onUpdateCorrect }: any) {
  const [editingTitle, setEditingTitle] = useState(false);
  const [draftTitle, setDraftTitle] = useState(title);
  useEffect(() => { if (!editingTitle) setDraftTitle(title); }, [title, editingTitle]);
  const commitTitle = () => { const nextTitle = draftTitle.trim(); if (nextTitle) onTitle(nextTitle); else setDraftTitle(title); setEditingTitle(false); };
  return <aside data-testid="ai-questions-column" className="min-w-0 flex-1 xl:w-[950px] xl:flex-none"><section className="w-full rounded-[24px] border border-[#172554]/10 bg-white shadow-[0_12px_30px_rgba(20,44,91,.06)]"><header className="border-b border-[#172554]/8 px-6 py-4"><div className="flex items-center gap-3">{editingTitle ? <Input autoFocus aria-label="Nhập tiêu đề Quiz trực tiếp" value={draftTitle} onChange={event => setDraftTitle(event.target.value)} onBlur={commitTitle} onKeyDown={event => { if (event.key === "Enter") commitTitle(); if (event.key === "Escape") { setDraftTitle(title); setEditingTitle(false); } }} className="h-9 max-w-[560px] border-0 bg-transparent px-0 text-lg font-bold text-[#172554] shadow-none focus-visible:ring-0" /> : <button type="button" onClick={() => setEditingTitle(true)} className="group flex min-w-0 items-center gap-2 text-left" aria-label="Chỉnh sửa tiêu đề Quiz"><span className="truncate text-lg font-bold text-[#172554]">{title || "Đặt tên cho Quiz"}</span><PencilLine size={16} className="shrink-0 text-[#71838d] transition-colors group-hover:text-[#065be5]" /></button>}</div></header><div data-testid="ai-questions-scroll" className="p-4"><QuestionRailCards questions={questions} selectedId={selectedId} draggedId={draggedId} onSelect={onSelect} onUpdate={onUpdate} onDuplicate={onDuplicate} onRemove={onRemove} onTypeChange={onTypeChange} onReorder={onReorder} onDragStart={onDragStart} onDragEnd={onDragEnd} onUpdateOption={onUpdateOption} onUpdateCorrect={onUpdateCorrect} /></div><footer className="border-t border-[#172554]/8 bg-[#fafffd] px-5 py-3 text-[11px] leading-4 text-[#007453]">Câu mới từ AI sẽ xuất hiện tại đây.</footer></section></aside>;
}

function QuestionRailCards({ questions, selectedId, draggedId, onSelect, onUpdate, onDuplicate, onRemove, onTypeChange, onReorder, onDragStart, onDragEnd, onUpdateOption, onUpdateCorrect }: any) {
  return <div className="mx-auto max-w-[650px] space-y-4">{questions.map((question: QuizQuestion, index: number) => <article key={question.id} draggable onDragStart={() => onDragStart(question.id)} onDragEnd={onDragEnd} onDragOver={event => event.preventDefault()} onDrop={() => { if (draggedId) onReorder(draggedId, question.id); onDragEnd(); }} onClick={() => onSelect(question.id)} className={`rounded-2xl border bg-white p-4 shadow-[0_2px_8px_rgba(20,44,91,.05)] transition ${selectedId === question.id ? "border-[#7057e8]/40 ring-2 ring-[#7057e8]/8" : "border-[#172554]/8 hover:border-[#065be5]/25"} ${draggedId === question.id ? "opacity-50" : ""}`}><div className="mb-4 flex items-center gap-2"><span title="Kéo để sắp xếp" className="cursor-grab text-[#aab4c4] active:cursor-grabbing"><GripVertical size={17} /></span><span className="text-base font-black text-[#25324d]">#{index + 1}</span><select aria-label={`Loại câu hỏi trong tab ${index + 1}`} value={question.type} onClick={event => event.stopPropagation()} onChange={event => onTypeChange(question.id, event.target.value as QuestionType)} className="h-9 min-w-0 flex-1 rounded-lg border border-[#172554]/10 bg-[#f8f9fc] px-2.5 text-xs font-bold text-[#35415a]"><option value="single">● Trắc nghiệm</option><option value="multiple">● Nhiều đáp án</option><option value="true_false">⇄ Đúng / Sai</option><option value="true_false_statements">▤ Nhận định Có / Không</option><option value="fill_blank">⌁ Trả lời ngắn</option><option value="matching">▦ Ghép nối</option><option value="essay">✎ Bài luận</option></select><div className="flex gap-1"><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onDuplicate(question); }} className="h-8 w-8 rounded-lg" aria-label={`Nhân bản câu hỏi ${index + 1} trong tab`}><Copy size={14} /></Button><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onRemove(question.id); }} className="h-8 w-8 rounded-lg text-[#de1264]" aria-label={`Xóa câu hỏi ${index + 1} trong tab`}><Trash2 size={14} /></Button></div></div><Textarea aria-label={`Nội dung câu hỏi ${index + 1} trong tab`} value={question.prompt} onClick={event => event.stopPropagation()} onChange={event => onUpdate(question.id, { prompt: event.target.value })} className="min-h-16 resize-none border-0 bg-transparent px-0 py-0 text-sm font-bold leading-6 shadow-none focus-visible:ring-0" placeholder="Nhập nội dung câu hỏi" />{["single", "multiple", "true_false"].includes(question.type) ? <div className="mt-4 space-y-2">{question.options.slice(0, 3).map((option: Option, optionIndex: number) => <div key={optionIndex} className="flex min-w-0 items-center gap-2.5"><button type="button" aria-label={`Đánh dấu đáp án ${optionIndex + 1} câu ${index + 1}`} onClick={event => { event.stopPropagation(); onUpdateCorrect(question, optionIndex); }} className={`grid h-5 w-5 shrink-0 place-items-center rounded-full text-[10px] ${option.isCorrect ? "bg-[#14c973] text-white" : "border border-[#cbd5e1] bg-white"}`}>{option.isCorrect ? <Check size={12} /> : ""}</button><Input aria-label={`Đáp án ${optionIndex + 1} câu ${index + 1} trong tab`} value={option.body} onClick={event => event.stopPropagation()} onChange={event => onUpdateOption(question, optionIndex, event.target.value)} className="h-8 border-0 bg-[#f8f9fc] px-2 text-sm text-[#617786] shadow-none focus-visible:ring-1" placeholder={`Tùy chọn ${optionIndex + 1}`} /></div>)}</div> : <p className="mt-4 text-xs text-[#71838d]">{questionTypes.find(item => item.value === question.type)?.label}</p>}</article>)}</div>;
}

function EditorCanvas({ questions, selectedId, highlightedIds, locked, onUpdate, onSelect, onDuplicate, onRemove, onAdd, onOpenAi, onReorder }: any) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  return <main className={`relative min-w-0 ${locked ? "pointer-events-none select-none" : ""}`}>
    <div className="mb-4 grid gap-2 rounded-2xl border border-[#7057e8]/14 bg-white p-3 shadow-[0_10px_24px_rgba(44,57,104,.04)] sm:grid-cols-4"><QuickAction icon={Sparkles} label="Nhập chủ đề" onClick={() => onOpenAi("topic")} /><QuickAction icon={FileText} label="Trích xuất tệp" onClick={() => onOpenAi("file")} /><QuickAction icon={Youtube} label="Từ YouTube" onClick={() => onOpenAi("youtube")} /><QuickAction icon={Globe2} label="Từ trang web" onClick={() => onOpenAi("web")} /></div>
    {locked ? <div data-testid="ai-editor-lock" className="absolute inset-0 z-20 grid place-items-center rounded-2xl bg-white/72 backdrop-blur-[2px]"><div className="flex items-center gap-3 rounded-2xl border border-[#7057e8]/20 bg-white px-5 py-4 shadow-xl"><Loader2 className="animate-spin text-[#7057e8]" /><div><p className="text-sm font-bold">AI đang tạo câu hỏi</p><p className="mt-0.5 text-xs text-[#71838d]">Editor tạm khóa để đồng bộ dữ liệu mới.</p></div></div></div> : null}
    <div className="space-y-4">{questions.map((question: QuizQuestion, index: number) => <QuestionCardV2 key={question.id} index={index} question={question} selected={question.id === selectedId} highlighted={highlightedIds.includes(question.id)} dragged={draggedId === question.id} onDragStart={() => setDraggedId(question.id)} onDragEnd={() => setDraggedId(null)} onDrop={() => { if (draggedId) onReorder(draggedId, question.id); setDraggedId(null); }} onSelect={() => onSelect(question.id)} onUpdate={(patch: Partial<QuizQuestion>) => onUpdate(question.id, patch)} onDuplicate={() => onDuplicate(question)} onRemove={() => onRemove(question.id)} />)}</div>
    <ManualQuestionBar onAdd={onAdd} />
  </main>;
}
function QuestionCardV2({ index, question, selected, highlighted, dragged, onDragStart, onDragEnd, onDrop, onSelect, onUpdate, onDuplicate, onRemove }: any) {
  const updateOptions = (options: Option[]) => onUpdate({ options });
  const changeType = (type: QuestionType) => { const defaults = createQuestion(type); onUpdate({ type, options: defaults.options, accepted: defaults.accepted, pairs: defaults.pairs, statements: defaults.statements, outline: defaults.outline }); };
  const setCorrect = (optionIndex: number) => updateOptions(question.options.map((option: Option, position: number) => ({ ...option, isCorrect: question.type === "multiple" ? position === optionIndex ? !option.isCorrect : option.isCorrect : position === optionIndex })));
  const validationError = question.prompt.trim().length < 8 ? "Cần nhập nội dung câu hỏi tối thiểu 8 ký tự." : validateQuestionConfiguration({ type: question.type, options: question.options, answerConfig: toAnswerConfig(question), imageUrl: question.imageUrl || null });
  return <article data-testid={`question-card-${question.id}`} draggable onDragStart={onDragStart} onDragEnd={onDragEnd} onDragOver={event => event.preventDefault()} onDrop={onDrop} onClick={onSelect} className={`rounded-2xl border bg-white p-4 shadow-[0_10px_24px_rgba(20,44,91,.045)] transition ${selected ? "border-[#065be5]/35 ring-2 ring-[#065be5]/7" : "border-[#172554]/10"} ${highlighted ? "border-[#7057e8]/45" : ""} ${dragged ? "opacity-50" : ""}`}>
    <div className="mb-4 flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-2"><GripVertical size={16} className="cursor-grab text-[#aab4c4] active:cursor-grabbing" /><span className="text-sm font-black">#{index + 1}</span><select aria-label={`Loại câu hỏi ${index + 1}`} value={question.type} onClick={event => event.stopPropagation()} onChange={event => changeType(event.target.value as QuestionType)} className="h-8 min-w-0 rounded-lg border border-[#172554]/10 bg-[#f8f9fc] px-2 text-xs font-bold text-[#35415a]"><option value="single">● Trắc nghiệm</option><option value="multiple">● Nhiều đáp án</option><option value="true_false">⇄ Đúng / Sai</option><option value="true_false_statements">▤ Nhận định Có / Không</option><option value="fill_blank">⌁ Trả lời ngắn</option><option value="matching">▦ Ghép nối</option><option value="essay">✎ Bài luận</option></select></div><div className="flex gap-1"><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onDuplicate(); }} className="h-8 w-8 rounded-lg" aria-label={`Nhân bản câu hỏi ${index + 1}`}><Copy size={14} /></Button><Button type="button" variant="outline" size="icon" onClick={event => { event.stopPropagation(); onRemove(); }} className="h-8 w-8 rounded-lg text-[#de1264]" aria-label={`Xóa câu hỏi ${index + 1}`}><Trash2 size={14} /></Button></div></div>
    <Label className="text-xs font-bold text-[#617786]">Nội dung câu hỏi <span className="text-[#de1264]">*</span></Label><Textarea value={question.prompt} onClick={event => event.stopPropagation()} onChange={event => onUpdate({ prompt: event.target.value })} className="mt-2 min-h-24 resize-none border-0 bg-transparent px-0 text-base font-semibold leading-7 shadow-none focus-visible:ring-0" placeholder="Vui lòng nhập câu hỏi." />
    <QuestionImageControl question={question} onUpdate={onUpdate} />
    {["single", "multiple", "true_false"].includes(question.type) ? <div className="mt-4 space-y-2">{question.options.map((option: Option, optionIndex: number) => <div key={optionIndex} className="flex items-center gap-2 rounded-xl bg-[#f8f9fc] px-3 py-2"><button type="button" onClick={event => { event.stopPropagation(); setCorrect(optionIndex); }} aria-label={`Đánh dấu đáp án ${optionIndex + 1} câu ${index + 1}`} className={`grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-bold ${option.isCorrect ? "bg-[#14c973] text-white" : "border border-[#cad3e1] bg-white text-[#71838d]"}`}>{option.isCorrect ? <Check size={14} /> : String.fromCharCode(65 + optionIndex)}</button><Input value={option.body} onClick={event => event.stopPropagation()} onChange={event => updateOptions(question.options.map((item: Option, position: number) => position === optionIndex ? { ...item, body: event.target.value } : item))} className="h-8 border-0 bg-transparent px-0 text-sm shadow-none focus-visible:ring-0" placeholder={`Tùy chọn ${optionIndex + 1}`} />{question.type !== "true_false" && question.options.length > 2 ? <button type="button" onClick={() => updateOptions(question.options.filter((_: Option, position: number) => position !== optionIndex))} className="text-[#aab4c4]" aria-label="Xóa phương án"><Trash2 size={14} /></button> : null}</div>)}{question.type !== "true_false" ? <button type="button" onClick={() => updateOptions([...question.options, { body: "", isCorrect: false }])} className="mt-1 text-xs font-bold text-[#065be5]">+ Thêm tùy chọn</button> : null}</div> : null}
    {question.type === "true_false_statements" ? <StatementComposer statements={question.statements} onChange={statements => onUpdate({ statements })} /> : null}
    {question.type === "fill_blank" ? <Input value={question.accepted} onChange={event => onUpdate({ accepted: event.target.value })} className="mt-4 h-10 bg-[#f8f9fc]" placeholder="Đáp án được chấp nhận, cách nhau bởi |" /> : null}
    {question.type === "matching" ? <div className="mt-4 space-y-2">{question.pairs.map((pair: any, pairIndex: number) => <div key={pairIndex} className="grid gap-2 sm:grid-cols-2"><Input value={pair.left} onChange={event => onUpdate({ pairs: question.pairs.map((item: any, position: number) => position === pairIndex ? { ...item, left: event.target.value } : item) })} placeholder="Vế A" /><Input value={pair.right} onChange={event => onUpdate({ pairs: question.pairs.map((item: any, position: number) => position === pairIndex ? { ...item, right: event.target.value } : item) })} placeholder="Vế B" /></div>)}<button type="button" onClick={() => onUpdate({ pairs: [...question.pairs, { left: "", right: "" }] })} className="text-xs font-bold text-[#065be5]">+ Thêm cặp ghép</button></div> : null}
    {question.type === "essay" ? <Textarea value={question.outline} onChange={event => onUpdate({ outline: event.target.value })} className="mt-4 min-h-20 bg-[#f8f9fc]" placeholder="Dàn ý hoặc đáp án mẫu" /> : null}
    <QuestionMediaControl question={question} onUpdate={onUpdate} />
    <details className="mt-4 rounded-xl bg-[#f8f9fc] px-3 py-2"><summary className="cursor-pointer text-xs font-bold text-[#617786]">Lời giải, độ khó và điểm</summary><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_130px_90px]"><Textarea value={question.explanation} onChange={event => onUpdate({ explanation: event.target.value })} className="min-h-16 bg-white text-xs" placeholder="Lời giải chi tiết" /><select value={question.difficulty} onChange={event => onUpdate({ difficulty: event.target.value as Difficulty })} className="h-9 rounded-md border border-[#172554]/10 bg-white px-2 text-xs"><option value="easy">Dễ</option><option value="medium">Trung bình</option><option value="hard">Khó</option></select><Input aria-label={`Điểm câu hỏi ${index + 1}`} type="number" min="1" max="100" value={question.points} onChange={event => onUpdate({ points: Math.min(100, Math.max(1, Number(event.target.value) || 1)) })} className="h-9 bg-white text-xs" /></div></details>
    {validationError ? <p role="alert" className="mt-3 rounded-lg bg-[#fff1f6] px-3 py-2 text-xs font-medium text-[#de1264]">{validationError}</p> : <p className="mt-3 text-[11px] font-medium text-[#007453]">Câu hỏi hợp lệ và sẽ tự lưu sau khi bạn dừng chỉnh sửa.</p>}
  </article>;
}

function StatementComposer({ statements, onChange }: { statements: Statement[]; onChange: (statements: Statement[]) => void }) {
  const update = (index: number, patch: Partial<Statement>) => onChange(statements.map((statement, position) => position === index ? { ...statement, ...patch } : statement));
  return <section className="mt-4 overflow-hidden rounded-xl border border-[#635BFF]/20 bg-[#fbfaff]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#635BFF]/12 px-3 py-2.5"><div><p className="text-xs font-bold text-[#25324d]">Nhận định chọn Có / Không</p><p className="mt-0.5 text-[10px] text-[#71838d]">Mỗi dòng là một nhận định độc lập; đáp án đúng được đánh dấu tại cột tương ứng.</p></div><Button type="button" variant="outline" onClick={() => onChange([...statements, createStatement(statements.length + 1)])} disabled={statements.length >= 8} className="h-8 rounded-lg px-2.5 text-[11px] text-[#635BFF]"><Plus size={13} />Thêm dòng</Button></div><div className="grid grid-cols-[minmax(0,1fr)_52px_68px_32px] border-b border-[#172554]/8 bg-white px-3 py-2 text-[9px] font-bold uppercase tracking-[.1em] text-[#71838d]"><span>Nhận định</span><span className="text-center">Có</span><span className="text-center">Không</span><span /></div>{statements.map((statement, statementIndex) => <div key={statement.id} className="grid grid-cols-[minmax(0,1fr)_52px_68px_32px] items-center gap-1 border-b border-[#172554]/7 px-3 py-2 last:border-0"><Input value={statement.text} onClick={event => event.stopPropagation()} onChange={event => update(statementIndex, { text: event.target.value })} className="h-8 border-0 bg-transparent px-0 text-sm shadow-none focus-visible:ring-0" placeholder={`Nhận định ${statementIndex + 1}`} /><button type="button" aria-pressed={statement.correct} onClick={() => update(statementIndex, { correct: true })} className={`mx-auto grid h-7 w-7 place-items-center rounded-full text-xs font-bold ${statement.correct ? "bg-success text-white" : "bg-success/10 text-success"}`}>✓</button><button type="button" aria-pressed={!statement.correct} onClick={() => update(statementIndex, { correct: false })} className={`mx-auto grid h-7 w-7 place-items-center rounded-full text-xs font-bold ${!statement.correct ? "bg-danger text-white" : "bg-danger/8 text-danger"}`}>×</button><button type="button" disabled={statements.length <= 2} onClick={() => onChange(statements.filter((_, position) => position !== statementIndex))} className="grid h-7 w-7 place-items-center rounded-md text-[#71838d] hover:bg-danger/8 hover:text-danger disabled:opacity-30" aria-label={`Xóa nhận định ${statementIndex + 1}`}><Trash2 size={13} /></button></div>)}</section>;
}

function QuestionMediaControl({ question, onUpdate }: { question: QuizQuestion; onUpdate: (patch: Partial<QuizQuestion>) => void }) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const upload = trpc.creator.uploadQuestionMedia.useMutation({ onSuccess: media => { onUpdate({ media }); toast.success(`${media.kind === "audio" ? "Audio" : "Video"} đã được tải lên.`); }, onError: error => toast.error("Không thể tải media", { description: error.message }) });
  const selectFile = (file?: File) => {
    if (!file) return;
    const kind = file.type.startsWith("audio/") ? "audio" : file.type.startsWith("video/") ? "video" : null;
    const allowed = ["audio/mpeg", "audio/mp4", "audio/x-m4a", "video/mp4", "video/webm"];
    const maxBytes = kind === "audio" ? 10 * 1024 * 1024 : 50 * 1024 * 1024;
    if (!kind || !allowed.includes(file.type)) { toast.error("Chỉ hỗ trợ MP3, M4A, MP4 hoặc WEBM."); return; }
    if (file.size > maxBytes) { toast.error(kind === "audio" ? "Audio tối đa 10 MB." : "Video tối đa 50 MB."); return; }
    const reader = new FileReader();
    reader.onload = () => upload.mutate({ fileName: file.name, kind, mimeType: file.type as "audio/mpeg" | "audio/mp4" | "audio/x-m4a" | "video/mp4" | "video/webm", base64: String(reader.result ?? "") });
    reader.onerror = () => toast.error("Không thể đọc tệp media.");
    reader.readAsDataURL(file);
  };
  return <div className="mt-4 rounded-xl border border-[#172554]/10 bg-[#fbfdff] p-3"><input ref={fileInputRef} type="file" accept=".mp3,.m4a,.mp4,.webm,audio/mpeg,audio/mp4,audio/x-m4a,video/mp4,video/webm" className="hidden" onChange={event => selectFile(event.target.files?.[0])} /><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold text-[#25324d]">Audio hoặc Video minh họa</p><p className="mt-0.5 text-[10px] text-[#71838d]">MP3/M4A tối đa 10 MB · MP4/WEBM tối đa 50 MB</p></div><Button type="button" variant="outline" onClick={() => fileInputRef.current?.click()} disabled={upload.isPending} className="h-8 rounded-lg text-xs text-[#065be5]">{upload.isPending ? <Loader2 className="animate-spin" size={14} /> : <FileText size={14} />}{upload.isPending ? "Đang tải" : "Đính kèm media"}</Button></div>{question.media ? <div className="mt-3 flex items-center gap-3 rounded-lg bg-white p-2"><div className="min-w-0 flex-1">{question.media.kind === "audio" ? <audio controls className="h-8 max-w-full" src={question.media.url} /> : <video controls className="max-h-44 w-full rounded-lg" src={question.media.url} />}<p className="mt-1 truncate text-[10px] text-[#71838d]">{question.media.fileName}</p></div><Button type="button" variant="outline" size="icon" onClick={() => onUpdate({ media: null })} className="h-8 w-8 shrink-0 rounded-lg text-[#de1264]" aria-label="Xóa media"><Trash2 size={14} /></Button></div> : null}</div>;
}

function QuestionImageControl({ question, onUpdate }: { question: QuizQuestion; onUpdate: (patch: Partial<QuizQuestion>) => void }) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const upload = trpc.creator.uploadQuestionImage.useMutation({ onSuccess: image => { onUpdate({ imageUrl: image.url }); toast.success("Đã tải ảnh minh họa cho câu hỏi."); }, onError: error => toast.error("Không thể tải ảnh minh họa", { description: error.message }) });
  const selectFile = (file?: File) => {
    if (!file) return;
    const allowed = ["image/jpeg", "image/png", "image/webp"];
    if (!allowed.includes(file.type)) { toast.error("Chỉ hỗ trợ ảnh JPG, PNG hoặc WEBP."); return; }
    if (file.size > 5 * 1024 * 1024) { toast.error("Ảnh minh họa tối đa 5 MB."); return; }
    const reader = new FileReader();
    reader.onload = () => upload.mutate({ fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", base64: String(reader.result ?? "") });
    reader.onerror = () => toast.error("Không thể đọc tệp ảnh.");
    reader.readAsDataURL(file);
  };
  return <div className="mt-4 rounded-xl border border-[#172554]/10 bg-[#fbfdff] p-3"><input ref={fileInputRef} type="file" accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp" className="hidden" onChange={event => selectFile(event.target.files?.[0])} /><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold text-[#25324d]">Ảnh minh họa</p><p className="mt-0.5 text-[10px] text-[#71838d]">JPG, PNG hoặc WEBP · tối đa 5 MB</p></div><Button type="button" variant="outline" onClick={() => fileInputRef.current?.click()} disabled={upload.isPending} className="h-8 rounded-lg text-xs text-[#065be5]" aria-label="Tải ảnh minh họa cho câu hỏi">{upload.isPending ? <Loader2 className="animate-spin" size={14} /> : <ImagePlus size={14} />}{upload.isPending ? "Đang tải" : question.imageUrl ? "Thay ảnh" : "Tải ảnh"}</Button></div>{question.imageUrl ? <div className="relative mt-3 overflow-hidden rounded-lg border border-[#172554]/10 bg-white"><img src={question.imageUrl} alt="Ảnh minh họa câu hỏi" className="max-h-72 w-full object-contain" /><Button type="button" variant="outline" size="icon" onClick={() => onUpdate({ imageUrl: "" })} className="absolute right-2 top-2 h-8 w-8 rounded-lg bg-white/95 text-[#de1264]" aria-label="Xóa ảnh minh họa"><Trash2 size={14} /></Button></div> : null}</div>;
}

